for await (const msg of query({ prompt: "Remember the word tulip.", options })) {
  if (msg.type === "result") sessionId = msg.session_id;
}

// later, maybe in another process: the same conversation goes on
for await (const msg of query({ prompt: "Which flower?", options: { ...options, resume: sessionId } })) {
  if (msg.type === "result" && msg.subtype === "success") console.log(msg.result);
}

import { mkdir, readdir, readFile, writeFile } from "node:fs/promises";
import { join } from "node:path";
import type { SessionKey, SessionStore, SessionStoreEntry } from "@anthropic-ai/claude-agent-sdk";

export class FolderSessionStore implements SessionStore {
  #seq = 0;
  #seen = new Set<string>();
  constructor(private readonly root: string) {}

  #dir(key: SessionKey) {
    const session = join(this.root, key.projectKey, key.sessionId);
    return key.subpath ? join(session, "sub", encodeURIComponent(key.subpath)) : join(session, "main");
  }

  async append(key: SessionKey, entries: SessionStoreEntry[]) {
    const fresh = entries.filter((e) => !e.uuid || !this.#seen.has(e.uuid));
    if (fresh.length === 0) return;
    const dir = this.#dir(key);
    await mkdir(dir, { recursive: true });
    const name = `part-${Date.now()}-${String(this.#seq++).padStart(6, "0")}.jsonl`;
    await writeFile(join(dir, name), fresh.map((e) => JSON.stringify(e)).join("\n"));
    for (const e of fresh) if (e.uuid) this.#seen.add(e.uuid);
  }

  // load() and listSubkeys(): see the lab
}

import { query } from "@anthropic-ai/claude-agent-sdk";
import { FolderSessionStore } from "./folder-store.js";

const resume = process.argv[2]; // run 2: the session ID that run 1 printed
const prompt = resume ? "Which flower did I ask you to remember?" : "Remember the word tulip. Reply with: noted.";

for await (const msg of query({
  prompt,
  options: {
    model: "claude-haiku-5-5",
    tools: [],
    settingSources: [],
    sessionStore: new FolderSessionStore("store"),
    resume,
    env: { ...process.env, CLAUDE_CONFIG_DIR: resume ? "/tmp/fresh-machine" : process.env.CLAUDE_CONFIG_DIR },
  },
})) {
  if (msg.type === "system" && msg.subtype === "mirror_error") console.log("store failed:", msg.error);
  if (msg.type === "result" && msg.subtype === "success") console.log(msg.result, "| session", msg.session_id);
}

