  }

  async listSubkeys(key: { projectKey: string; sessionId: string }) {
    const names = await readdir(join(this.root, key.projectKey, key.sessionId, "sub")).catch(() => []);
    return names.map((n) => decodeURIComponent(n));
  }
}
