import assert from "node:assert/strict";
import { mkdtemp } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { test } from "node:test";
import { InMemorySessionStore, type SessionStore } from "@anthropic-ai/claude-agent-sdk";
import { FolderSessionStore } from "../src/folder-store.js";

const key = { projectKey: "-work-fcp", sessionId: "9c1f0b7e-0000-4000-8000-000000000001" };
const batch = [{ type: "user", uuid: "u1" }, { type: "assistant", uuid: "u2" }];

const contract = (name: string, make: () => Promise<SessionStore>) => {
  test(`${name}: unknown session loads as null`, async () => assert.equal(await (await make()).load(key), null));
  test(`${name}: a retried batch is stored once`, async () => {
    const store = await make();
    await store.append(key, batch);
    await store.append(key, batch);
    assert.equal((await store.load(key))!.length, 2);
  });
};

contract("folder", async () => new FolderSessionStore(await mkdtemp(join(tmpdir(), "store-"))));
contract("in-memory", async () => new InMemorySessionStore());
